UPDATE TBL_INVESTMENT_PRODUCT
SET PRODUCT_STATUS = #{status}, UPDATED_TIME = CURRENT_TIMESTAMP
WHERE PRODUCT_ID = #{productId}

UPDATE TBL_INVESTMENT_PRODUCT
SET NET_VALUE = #{netValue}, UPDATED_TIME = CURRENT_TIMESTAMP
WHERE PRODUCT_ID = #{productId}
